fn hex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex byte"))
        .collect()
}

fn fmt_bytes(s: Option<&[u8]>) -> String {
    match s {
        None => "-".to_string(),
        Some(b) => format!(
            "s:{}",
            b.iter().map(|c| format!("{c:02x}")).collect::<String>()
        ),
    }
}

fn fnv(mut hash: u64, value: u64) -> u64 {
    for shift in (0..64).step_by(8) {
        hash ^= (value >> shift) & 0xff;
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    hash
}

fn hash_model(hash: u64, m: &Model) -> u64 {
    let mut h = fnv(hash, u64::from(m.shiftsleft));
    h = fnv(h, m.entries as u64);
    for s in &m.syms {
        h = fnv(h, u64::from(s.sym));
        h = fnv(h, u64::from(s.cumfreq));
    }
    m.tabloc.iter().fold(h, |acc, &t| fnv(acc, u64::from(t)))
}

fn hash_qtm(s: &QtmState) -> u64 {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    for &v in &s.length_base {
        h = fnv(h, u64::from(v));
    }
    for &v in &s.length_extra {
        h = fnv(h, u64::from(v));
    }
    for &v in &s.extra_bits {
        h = fnv(h, u64::from(v));
    }
    for &v in &s.position_base {
        h = fnv(h, u64::from(v));
    }
    [
        &s.model7,
        &s.model00,
        &s.model40,
        &s.model80,
        &s.model_c0,
        &s.model4,
        &s.model5,
        &s.model6pos,
        &s.model6len,
    ]
    .into_iter()
    .fold(h, hash_model)
}

fn header_line(h: &CabinetHeader<'_>) -> String {
    let (header, folder, block) = h
        .reserve
        .as_ref()
        .map_or((0, 0, 0), |r| (r.header, r.folder, r.data));
    let prev = h.prev.as_ref();
    let next = h.next.as_ref();
    format!(
        "ret=1 err=0 cab={} folders={} files={} setid={} index={} reserve={} hdr={header} folder={folder} block={block} hasprev={} hasnext={} prev={} previnfo={} next={} nextinfo={}",
        h.cab_size,
        h.folders,
        h.files,
        h.set_id,
        h.index,
        u8::from(h.reserve.is_some()),
        u8::from(prev.is_some()),
        u8::from(next.is_some()),
        fmt_bytes(prev.map(|l| l.name)),
        fmt_bytes(prev.and_then(|l| l.info)),
        fmt_bytes(next.map(|l| l.name)),
        fmt_bytes(next.and_then(|l| l.info)),
    )
}

fn replay(cmd: &str) -> String {
    let parts: Vec<&str> = cmd.split(' ').collect();
    match parts.as_slice() {
        ["checksum", data, seed] => {
            let seed = u32::from_str_radix(seed, 16).expect("checksum seed");
            format!("sum={:08x}", checksum(&hex(data), seed))
        }
        ["decode", nbits, lengths] => {
            let nbits: u32 = nbits.parse().expect("decode nbits");
            let lengths = hex(lengths);
            let mut table = vec![0u16; (1usize << nbits) + 2 * lengths.len()];
            let ret = i32::from(make_decode_table(nbits, &lengths, &mut table).is_err());
            let entries: Vec<String> = table.iter().map(|t| format!("{t:04x}")).collect();
            format!("ret={ret} table={}", entries.join(","))
        }
        ["qtm_init", window] => match QtmState::init(window.parse().expect("qtm window")) {
            Ok(state) => format!("ret=0 hash={:016x}", hash_qtm(&state)),
            Err(e) => format!("ret={} hash=-", e.code()),
        },
        ["qtm_update", entries, start, sym, count] => {
            let entries: usize = entries.parse().expect("qtm entries");
            let start: usize = start.parse().expect("qtm start");
            let sym: usize = sym.parse().expect("qtm sym");
            let count: usize = count.parse().expect("qtm count");
            let mut model = Model::new(entries, start);
            for _ in 0..count {
                model.update(sym);
            }
            let syms: Vec<String> = model
                .syms
                .iter()
                .map(|s| format!("{}:{}", s.sym, s.cumfreq))
                .collect();
            let tab: Vec<String> = (start..start + entries)
                .map(|t| model.tabloc[t].to_string())
                .collect();
            format!(
                "ret=0 shift={} syms={} tab={}",
                model.shiftsleft,
                syms.join(","),
                tab.join(",")
            )
        }
        ["header", data] => {
            let bytes = hex(data);
            match read_header(&bytes) {
                Ok(h) => header_line(&h),
                Err(e) => format!("ret=0 err={}", e.code()),
            }
        }
        ["iscab", data] => {
            let bytes = hex(data);
            match is_cabinet(&bytes) {
                Ok(h) => format!(
                    "ret=1 cab={} folders={} files={} setid={} index={} reserve={} hasprev={} hasnext={}",
                    h.cab_size,
                    h.folders,
                    h.files,
                    h.set_id,
                    h.index,
                    u8::from(h.reserve.is_some()),
                    u8::from(h.prev.is_some()),
                    u8::from(h.next.is_some()),
                ),
                Err(_) => "ret=0".to_string(),
            }
        }
        _ => panic!("unknown oracle command: {cmd}"),
    }
}

#[test]
fn oracle_vectors_match_wine() {
    for (cmd, expected) in VECTORS {
        assert_eq!(replay(cmd), *expected, "{cmd}");
    }
}

#[test]
#[should_panic(expected = "unknown oracle command")]
fn unknown_command_is_rejected() {
    replay("nope 1");
}
